def decide_retry_prepare(self, job: dict, actor: str, action: str, note: str) -> dict:
    store.prepare(job["id"], {})
    return self.move(job, job["stage"], needs=None)

def decide_ship_anyway(self, job: dict, actor: str, action: str, note: str) -> dict:
    # Over this one finding, not over the tiers still to come: a review
    # blocker waved through still goes to prove.
    following = {"checks": "verify" if job.get("spec") else after_green(job), "verify": after_green(job),
                 "strengthened": after_green(job), "refactor": "acceptance", "acceptance": after_green(job),
                 "review": "ship",
                 "prove": "comprehend"}
    heard(job, actor, job["stage"], f"accepted and continued past {(job.get('needs') or {}).get('kind', 'a finding')}: "
          f"{str((job.get('needs') or {}).get('text', ''))[:300]}", note)
    job.setdefault("shipped_over", []).append({**(job.get("needs") or {}), "by": actor,
                                               "stage": job["stage"]})
    return self.move(job, following.get(job["stage"], "ship"), needs=None)

def decide_revise(self, job: dict, actor: str, action: str, note: str) -> dict:
    feedback = note.strip() or (job.get("review") or {}).get("text", "")
    if note.strip():
        heard(job, actor, job["stage"], "sent the change back", note)
    job["revise"] = {"from": "review" if action == "revise" else "a reviewer",
                     "feedback": feedback[:12000], "back_to": "checks"}
    job["revisions"] = {}
    return self.move(job, "implement", needs=None)

def decide_merge(self, job: dict, actor: str, action: str, note: str) -> dict:
    """Merge the pull request — only the commit this factory pushed, and only
    once CI on it is green. The repository's own pipeline deploys on merge;
    the job then watches that deploy (see `watch_cd`)."""
    if job.get("state") != "waiting" or job.get("stage") != "preview" or not job.get("pr_url"):
        raise Refused("only a job whose pull request is open, and signed off in UAT, can be merged")
    if (job.get("signoff") or {}).get("sha") != job.get("pushed_sha"):
        raise Refused("UAT has not been signed off for the commit that would be merged")
    status = forge.ci_status(job)
    job["ci"] = {**status, "checked": store.now()}
    refusal = merge_refusal(job, status)
    if refusal:
        store.save(job)
        raise Refused(refusal)
    sha = forge.merge_pr(job)
    self.note(job, f"merged by {actor} at {sha[:10]}; the repository's pipeline deploys from here")
    # `head`: the commit GitHub was told to merge (forge.merge_pr's sha=), so the
    # record shows it was the one signed off on (traces.py, noUnsignedMerge).
    store.audit(actor, "merged", job=job["id"], pr=job["pr_url"], sha=sha, head=job["pushed_sha"])
    return self.start_deploy(job, sha, actor)

def start_deploy(self, job: dict, sha: str, actor: str = "") -> dict:
    job["merged"] = {"sha": sha, "by": actor, "at": store.now()}
    # The sprite is kept for learn, the job's last turn, and torn down when
    # the job lands (`land`).
    return self.move(job, "deploy", "waiting", needs=None)

def land(self, job: dict, stage: str) -> dict:
    """Merged, deployed, and learned from: the sprite goes, if merging left it."""
    life = (job.get("settings") or {}).get("lifetime") or config.LIFETIME
    if life.get("destroy_on_merge", True):
        self.teardown(job)
    return self.move(job, stage, "landed")

def do_deploy(self, job: dict) -> None:
    """Retry from a failed deploy: watch the merge commit's checks again (after
    someone re-runs the pipeline on GitHub)."""
    job["cd"] = {}
    self.move(job, "deploy", "waiting")

def watch_cd(self, job: dict, now: float) -> str | None:
    """The checks on the merge commit — the repository's CI and CD on the base
    branch. Green lands the job; red stops for a person, because a fix to the
    base branch is not this job's to make unasked."""
    sha = (job.get("merged") or {}).get("sha")
    if not sha:
        return None
    status = forge.commit_checks(job, sha, self.repo(job).get("deploy_checks") or [])
    job["cd"] = {**status, "checked": now}
    if status["state"] in ("pass", "none"):
        self.note(job, "deployed: every check on the merge commit passed"
                  if status["state"] == "pass" else "merged; the merge commit ran no checks")
        if learn.evidence(job):
            self.move(job, "learn")
        else:
            self.note(job, "nothing went wrong or was overridden; nothing to learn from")
            self.land(job, "deploy")
        return "landed"
    if status["state"] == "fail":
        names = ", ".join(f"[{f['name']}]({f['link']})" for f in status["failed"])
        escapes.record(job, "cd_failed", f"the pipeline on the merge commit failed: {names}", sha=sha)
        self.need(job, "stuck", f"The merge went in, but the pipeline on the merge commit "
                                f"failed: {names}.\n\nRe-run it on GitHub, or fix the base "
                                f"branch, then retry here.", ["retry", "stop"])
        return "cd_failed"
    hours = float(((job.get("settings") or {}).get("lifetime") or {}).get("deploy_hours", 2))
    if now - (job.get("merged") or {}).get("at", now) > hours * 3600:
        self.need(job, "stuck", f"The pipeline on the merge commit has not finished in "
                                f"{hours:g}h.", ["retry", "stop"])
        return "cd_stalled"
    store.save(job)
    return None

# learn — after it is deployed: what should change for the next job (L1)

def do_learn(self, job: dict) -> None:
    """Never holds a landing back: no evidence is no turn, and a turn that
    fails lands the job without proposals."""
    items = learn.evidence(job)
    if not items:
        self.note(job, "nothing went wrong or was overridden; nothing to learn from")
        return self.land(job, "learn")
    store.trace("trace.learn.evidence", job["id"], requester=job.get("requester"), evidence=items)
    if job.get("destroyed"):
        self.sprite_for_learn(job)
    self.start_turn(job, "learn", learn.brief(job, items), evidence=len(items))

def sprite_for_learn(self, job: dict) -> None:
    """Learn runs in the job's sprite, like every turn. An escape found after
    the job landed (a revert, a bug traced to it) is learned from when that
    sprite is long gone, and those are what learn is most for: so learn,
    which reads what it is given and needs no repository, gets a bare sprite
    of the job's own name, torn down again when it lands."""
    sandbox.create(job)
    job["destroyed"] = None
    store.save(job)
    problem = (sprite_runtime.install(self.trigger, job, lambda line: self.note(job, line))
               or sprite_runtime.apply_policy(self.trigger, job, self.repo(job)))
    if problem:
        raise RuntimeError(problem)
    self.note(job, f"its sprite was gone; {job['sprite']} is a bare one for learn's turn")

def after_learn(self, job: dict, reply: str, turn: dict) -> None:
    items = learn.evidence(job)
    found, dropped = learn.read(parse.json_block(reply), job, items)
    filed = [learn.file(p, job, "learn") for p in found]
    job["learned"] = {"at": store.now(), "evidence": len(items), "proposals": [p["id"] for p in filed],
                      "dropped": dropped}
    job.pop("relearn", None)
    store.trace("trace.learn.proposed", job["id"], proposals=found, filed=[p["id"] for p in filed],
                dropped=dropped)
    for line in dropped:
        self.note(job, f"learn: dropped {line}")
    self.note(job, f"learned: {len(filed)} proposal(s) for the Constraints page")
    self.land(job, "learn")

def decide_extend(self, job: dict, actor: str, action: str, note: str) -> dict:
    # A review can take longer than an idle timer. Saving the record is
    # what resets the clock the reaper reads.
    return store.save(job)

def decide_revive(self, job: dict, actor: str, action: str, note: str) -> dict:
    if job.get("state") != "waiting" or not job.get("destroyed"):
        raise Refused("only a preview that was torn down can be revived")
    job["destroyed"] = None
    store.prepare(job["id"], {})
    return self.move(job, "revive", "ready")

def accept_repo(self, actor: str, job_id: str, block_yaml: str) -> dict:
    import yaml
    job = self.expect(job_id, "onboard")
    try:
        block = yaml.safe_load(block_yaml) or {}
    except yaml.YAMLError as exc:
        raise Refused(f"that is not valid YAML: {exc}") from exc
    if not isinstance(block, dict):
        raise Refused("the settings block must be a mapping")
    block = {**{k: v for k, v in (job.get("settings") or {}).items()
                if k in ("remote", "base", "branch_prefix", "workdir")}, **block}
    block.pop("notes", None)
    write_repo(job["repo"], block)
    store.audit(actor, "accept_repo", job=job_id, repo=job["repo"])
    self.teardown(job)
    return self.move(job, job["stage"], "landed", needs=None)

def stop(self, actor: str, job_id: str) -> dict:
    job = self.load(job_id)
    if job.get("turn"):
        harness.stop(self.trigger, job["turn"])
        gate.end_session(job["turn"]["session_id"])
        harness.record_session(self.trigger, job, job["turn"], f"stopped by {actor}")
    store.audit(actor, "stop", job=job_id)
    return self.move(job, job["stage"], "stopped", turn=None, needs=None)

